CREATE ROLE service_role;CREATE ROLE authenticated;CREATE ROLE anon;
 CREATE TABLE profiles(id uuid PRIMARY KEY,role text);
 CREATE TABLE ca_horse_fleet_policy(scope text NOT NULL,scope_id uuid,scope_key uuid GENERATED ALWAYS AS(COALESCE(scope_id,'00000000-0000-0000-0000-000000000000'::uuid)) STORED,
 enabled boolean DEFAULT true,pause_new_seatings boolean DEFAULT false,max_horses integer,max_per_table integer,occupancy_bias numeric DEFAULT 1.0,min_humans_to_seat integer DEFAULT 0,stake_bands text[],variants text[],schedule jsonb,notes text,updated_by uuid,updated_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(scope,scope_key),CHECK(scope IN('global','club','union')),CHECK((scope='global')=(scope_id IS NULL)),CHECK(COALESCE(max_horses,0)>=0 AND COALESCE(max_per_table,0)>=0),CHECK(occupancy_bias IS NULL OR(occupancy_bias>0 AND occupancy_bias<=10)),CHECK(min_humans_to_seat IS NULL OR min_humans_to_seat BETWEEN 0 AND 10));
 CREATE TABLE admin_audit_log(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),admin_user_id uuid,action text NOT NULL,target_type text,target_id text,details jsonb DEFAULT '{}',ip_address text,created_at timestamptz DEFAULT now(),before_state jsonb,after_state jsonb,user_agent text,actor_role text,request_id text);
